package cn.kejian;
import android.content.*;import org.json.*;import java.time.*;import java.util.*;
public final class LocalTables {
 public static JSONObject blank()throws Exception{return blank(School.WFU);}
 static JSONObject blank(School school)throws Exception{LocalDate start=LocalDate.now(ScheduleLogic.ZONE).with(java.time.DayOfWeek.MONDAY);JSONArray weeks=new JSONArray();for(int i=0;i<20;i++)weeks.put(new JSONObject().put("number",i+1).put("start",start.plusWeeks(i).toString()).put("end",start.plusWeeks(i).plusDays(6).toString()).put("state","empty").put("courses",new JSONArray()));return new JSONObject().put("school",school.name()).put("periods",new JSONArray()).put("updated",System.currentTimeMillis()).put("weeks",weeks);}
 public static List<Integer> visible(ScheduleRepository repo){int first=0,last=repo.weeks.size()-1;while(first<=last&&empty(repo,first))first++;while(last>=first&&empty(repo,last))last--;List<Integer> out=new ArrayList<>();if(first>last){first=0;last=repo.weeks.size()-1;}for(int i=first;i<=last;i++)out.add(i);return out;}
 private static boolean empty(ScheduleRepository repo,int i){ScheduleRepository.Week w=repo.weeks.get(i);return w.known()&&repo.courses.stream().noneMatch(c->!c.date.isBefore(w.start)&&!c.date.isAfter(w.end));}
 public static JSONObject edit(JSONObject old,ScheduleLogic.Course original,LocalDate date,String name,String room,String teacher,int first,int last,boolean delete)throws Exception{JSONObject data=new JSONObject(old.toString());JSONArray weeks=data.getJSONArray("weeks");JSONObject target=null;String term="LOCAL";for(int i=0;i<weeks.length();i++){JSONObject w=weeks.getJSONObject(i);JSONArray cs=w.getJSONArray("courses");for(int j=cs.length()-1;j>=0;j--){JSONObject c=cs.getJSONObject(j);term=c.optString("XNXQDM",term);if(original!=null&&c.optString("KBID").equals(original.id)&&!original.date.isBefore(LocalDate.parse(w.getString("start")))&&!original.date.isAfter(LocalDate.parse(w.getString("end"))))cs.remove(j);}LocalDate start=LocalDate.parse(w.getString("start"));if(!date.isBefore(start)&&!date.isAfter(start.plusDays(6)))target=w;}
 if(target==null)throw new IllegalArgumentException("日期不在此课表范围，请选择范围内日期或新建课表");if(!delete){target.getJSONArray("courses").put(new JSONObject().put("KBID",UUID.randomUUID().toString()).put("XNXQDM",term).put("KCM",name).put("JSMC",room).put("SKLS",teacher).put("SKXQ",date.getDayOfWeek().getValue()).put("KSJC",first).put("JSJC",last));target.put("state","ok");}data.put("updated",System.currentTimeMillis());return data;}
 public static void saveNamed(Context c,String name,JSONObject raw)throws Exception{JSONObject copy=new JSONObject(raw.toString());copy.remove("profile");String id=UUID.randomUUID().toString();c.getSharedPreferences("tables",0).edit().putString(id,new JSONObject().put("name",name).put("data",copy).toString()).apply();}
 public static void deleteNamed(Context c,String id){
  c.getSharedPreferences("tables",0).edit().remove(id).apply();
 }
}
